import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")

    if platform.system() == "Windows":
        cmd = 'typeperf "\\Processor(_Total)\\% Processor Time" -sc 1'
    else:
        cmd = "top -bn1 | grep 'Cpu(s)' | awk '{print $2}'"

    records = []
    start_time = time.time()
    next_time = start_time + interval

    while time.time() - start_time < duration:
        time.sleep(max(0, next_time - time.time()))
        try:
            output = subprocess.check_output(cmd, shell=True).decode()
            if platform.system() == "Windows":
                cpu_percent = float(output.strip().split(',')[-1].replace('"', ''))
            else:
                cpu_percent = float(output.strip().split('%')[0])
        except:
            cpu_percent = 0.0

        records.append({
            "timestamp": time.time(),
            "cpu_percent": cpu_percent
        })
        next_time += interval

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None

    return LOGFILE_PATH

